# Free - API Key Vendaam - DuckDuckGo + Wikipedia - Free!
def web_search(query):
    # Web Search - 2 Edathula Theduven - DuckDuckGo + Wikipedia - Free!
    results = []
    try:
        # 1. DuckDuckGo - Instant Answer - Free - Key Vendaam!
        r = requests.get('https://api.duckduckgo.com/', params={'q': query, 'format': 'json', 'no_html': 1, 'skip_disambig': 1}, timeout=10)
        if r.status_code == 200:
            j = r.json()
            if j.get('AbstractText'): results.append(j['AbstractText'][:1000])
            for topic in j.get('RelatedTopics', [])[:3]:
                if isinstance(topic, dict) and topic.get('Text'): results.append(topic['Text'][:500])
        print(f'Web Search - DuckDuckGo - {len(results)} Results - {query[:30]}', flush=True)
    except Exception as e: print(f'DuckDuckGo Err {e}', flush=True)
    try:
        # 2. Wikipedia - Free - Key Vendaam!
        r2 = requests.get('https://en.wikipedia.org/api/rest_v1/page/summary/' + query.replace(' ', '_'), timeout=10)
        if r2.status_code == 200:
            j2 = r2.json()
            if j2.get('extract'): results.append(j2['extract'][:1000]); print(f'Web Search - Wikipedia - OK - {query[:30]}', flush=True)
    except Exception as e: print(f'Wikipedia Err {e}', flush=True)
    if not results: print('Web Search - No Results - Groq Mattum Use Pannuren', flush=True); return ''
    combined = '\n\n'.join(results)[:2000]
    print(f'Web Search Done - {len(combined)} chars - AI ku Kodukuren', flush=True)
    return combined
def needs_web_search(q):
    # Eppadi Kelvi ku Web Search Venum? - Pudhu News / Ippo / Latest nu Kettalum Web Search!
    low = q.lower()
    words = ['ippo','iniki','today','latest','news','pudhu','current','eppo','nadanthuchu','enna news','weather','cricket score','match','price','rate','stock','movie release','election','rain','velai','job opening']
    return any(w in low for w in words) or '?' in q and any(w in low for w in ['yaaru jeyichanga','enna aachu','eppa','latest'])
# ============ WEB ACCESS - Full Ah On! - Ippo Web Access! ============
# Web Access na - Bot - Internet la Enna Venum naalum Paakka Mudiyum!
# Web Search - News / Latest / Pudhu Info - Theduvum!
# Web Fetch - Link Kudutha - Andha Link ah Open Panni Padikkum!
# Example: Ne Link Anuppa - https://en.wikipedia.org/wiki/Thirukkural - Bot - Andha Page ah Padichu Sollum!
def web_fetch(url):
    # Link Kudutha - Andha Link ah Open Panni Padikkum - Web Access!
    try:
        print(f'Web Access - Fetching - {url[:60]}', flush=True)
        r = requests.get(url, headers={'User-Agent':'AiraH1'}, timeout=15)
        if r.status_code==200:
            txt = r.text[:5000]
            # HTML Tag ah Thookidu - Text Mattum Edu!
            import re; txt = re.sub('<[^>]+>', ' ', txt); txt = ' '.join(txt.split())[:3000]
            print(f'Web Access - Fetch OK - {len(txt)} chars', flush=True); return txt
        print(f'Web Access - Fetch Fail - {r.status_code}', flush=True); return ''
    except Exception as e: print(f'Web Fetch Err {e}', flush=True); return ''
def web_access_full(q):
    # Web Access - Full Ah On! - Ella Kelvi kum Web Paakkum!
    # 1. Link Irukka Paaru - Link Irukku na - Fetch Pannu!
    import re
    urls = re.findall(r'https?://\S+', q)
    web_info = ''
    if urls:
        for u in urls: web_info += web_fetch(u) + '\n\n'
        print(f'Web Access - Link Found - {urls} - Fetch Panniten!', flush=True)
    # 2. Web Search - Ella Kelvi kum - Web la Thedu!
    ws = web_search(q)
    if ws: web_info += ws
    if web_info:
        q2 = f'{q} - Web Access la Kedaicha Pudhu Info: {web_info[:2000]} - Itha Vechnu Full Paragraph Katha Tanglish la sollu'
        print(f'Web Access - Full - {len(web_info)} chars - AI ku Kodukuren', flush=True)
        return ai_answer(q2)
    print('Web Access - No Web Info - Groq Mattum', flush=True); return ai_answer(q)
# Ippo - Web Access Full Ah On! - Listen la - ai_answer_with_web ku Badhila - web_access_full Use Pannu!
def ai_answer_with_web(q):
    # Web Search + AI - Rendum Serthu - Full Paragraph Answer!
    web_info = ''
    if needs_web_search(q):
        print(f'Web Search Needed - {q[:40]} - Web la Theduren...', flush=True)
