def full_analysis_channel(kind, topic, raw_text):
    prompt=f"{topic} pathi FULL ANALYSIS pannu - Tanglish la - Full Paragraph la sollu - Single line la sollatha - Enna nadanthuchu, yen nadanthuchu, enna kathukkanum - Ellame Oru Full Paragraph Katha la sollu. Raw: {raw_text[:800]}"
    analysis=ai_answer(prompt); full_msg=f"📊 FULL ANALYSIS - {kind.upper()} - {topic}\n\n{analysis}"
    print(f"Full Analysis - {kind} - {topic} - Books Fix - Correct Edathuku Anupuren...", flush=True)
    if kind=="book": send_books(full_msg)
    elif kind in ["emotion","qa","knowledge"]: send_chat(full_msg)
    else: send_data(full_msg)
    save_batch(kind, full_msg); update_total(kind,1); update_total("analysis",1); print(f"Full Analysis Done - {kind} - {topic}!", flush=True); return full_msg
